window.ScripturaLexicons.BDAG_PART_0379 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-01\" data-source=\"BDAG\" data-search=\"φιλότεκνος, ον adjetivo amoroso para com os filhos; indulgente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φιλότεκνος, ον</td><td>adjetivo</td><td>amoroso para com os filhos; indulgente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-02\" data-source=\"BDAG\" data-search=\"φιλοτιμέομαι verbo ter por ambição; considerar uma honra; aspirar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φιλοτιμέομαι</td><td>verbo</td><td>ter por ambição; considerar uma honra; aspirar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-03\" data-source=\"BDAG\" data-search=\"φιλοτιμία, ας, ἡ substantivo feminino zelo generoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φιλοτιμία, ας, ἡ</td><td>substantivo feminino</td><td>zelo generoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-04\" data-source=\"BDAG\" data-search=\"φιλόϋλος, ον adjetivo amante das coisas materiais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φιλόϋλος, ον</td><td>adjetivo</td><td>amante das coisas materiais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-05\" data-source=\"BDAG\" data-search=\"φιλοφρόνως advérbio amigavelmente; hospitaleiramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φιλοφρόνως</td><td>advérbio</td><td>amigavelmente; hospitaleiramente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-06\" data-source=\"BDAG\" data-search=\"φιλόφρων, ον, adjetivo bem-disposto; amigável; bondoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φιλόφρων, ον,</td><td>adjetivo</td><td>bem-disposto; amigável; bondoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-07\" data-source=\"BDAG\" data-search=\"Φίλων, ωνος, ὁ nome próprio masculino Fílon BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φίλων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Fílon</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-08\" data-source=\"BDAG\" data-search=\"φιμόω verbo amordaçar; silenciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φιμόω</td><td>verbo</td><td>amordaçar; silenciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-09\" data-source=\"BDAG\" data-search=\"φλαγελλόω verbo; remissão v. φραγελλόω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φλαγελλόω</td><td>verbo; remissão</td><td>v. φραγελλόω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-10\" data-source=\"BDAG\" data-search=\"φλέγω verbo arder; inflamar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φλέγω</td><td>verbo</td><td>arder; inflamar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-11\" data-source=\"BDAG\" data-search=\"Φλέγων, οντος, ὁ nome próprio masculino Flegonte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φλέγων, οντος, ὁ</td><td>nome próprio masculino</td><td>Flegonte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-12\" data-source=\"BDAG\" data-search=\"φλέψ, φλεβός, ἡ substantivo feminino veia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φλέψ, φλεβός, ἡ</td><td>substantivo feminino</td><td>veia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-13\" data-source=\"BDAG\" data-search=\"φλογίζω verbo incendiar; atear fogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φλογίζω</td><td>verbo</td><td>incendiar; atear fogo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-14\" data-source=\"BDAG\" data-search=\"φλόξ, φλογός, ἡ substantivo feminino chama BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φλόξ, φλογός, ἡ</td><td>substantivo feminino</td><td>chama</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-15\" data-source=\"BDAG\" data-search=\"φλυαρέω verbo dizer disparates; difamar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φλυαρέω</td><td>verbo</td><td>dizer disparates; difamar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-16\" data-source=\"BDAG\" data-search=\"φλύαρος, ον adjetivo mexeriqueiro; dado a fofocas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φλύαρος, ον</td><td>adjetivo</td><td>mexeriqueiro; dado a fofocas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-17\" data-source=\"BDAG\" data-search=\"φοβερός, ά, όν adjetivo temível; terrível; assustador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φοβερός, ά, όν</td><td>adjetivo</td><td>temível; terrível; assustador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-18\" data-source=\"BDAG\" data-search=\"φοβέω verbo temer; ter medo; respeitar; reverenciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φοβέω</td><td>verbo</td><td>temer; ter medo; respeitar; reverenciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-19\" data-source=\"BDAG\" data-search=\"φόβητρον e φόβηθρον substantivo neutro portento terrível; horror BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φόβητρον e φόβηθρον</td><td>substantivo neutro</td><td>portento terrível; horror</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0379-20\" data-source=\"BDAG\" data-search=\"φόβος, ου, ὁ substantivo masculino intimidação; terror; medo; reverência; respeito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φόβος, ου, ὁ</td><td>substantivo masculino</td><td>intimidação; terror; medo; reverência; respeito</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0379-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλότεκνος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φιλότεκνος</span>, <span class=\"greek\">ον</span> (Eur., Hdt.+; ins: ZAly, Some Funerary Stelae fr. Kom Abou Bellou ’49, p. 37 linha 2 de uma mãe que ama seus filhos ou é amada por eles; p. 23, linha 1f de Héracles ‘amado por seus filhos’; PMich 149, 18, 2 [II d.C.]; PCairMasp 20, 10; 4 Macc 15:4f; JosAs 12:8; Philo, Abr. 179) amante dos próprios filhos, especialmente de mulheres (Aristoph. e outros) com <span class=\"greek\">φίλανδρος</span> (Plut., Mor. 769c; inscrição de Pérgamo [Dssm., LO4 268=LAE 315] <span class=\"greek\">γυναικὶ</span> <span class=\"greek\">φιλάνδρῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φιλοτέκνῳ</span>; Sb 330, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:4.</a> De um pai (SEG XXVIII, 1493, 6f [I/II d.C.]) em sentido de censura (Synes., Ep. 1 p. 157d <span class=\"greek\">φιλότεκνος</span> de um progenitor indulgente; Lucian, Tyrannic. 4 <span class=\"greek\">φ</span>. <span class=\"greek\">ἐς</span> <span class=\"greek\">ὑπερβολήν</span>) <span class=\"greek\">φ</span>. <span class=\"greek\">ὤν</span> porque és indulgente Hv 1, 3, 1 (Leutzsch, Hermas 388, 91).—DELG s.v. <span class=\"greek\">τίκτω</span>. New Docs 2 p. 64 ins n.º 5, 28, cf. p. 101; 3 p. 42f (lista de inscrições). M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτιμέομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φιλοτιμέομαι</span> depoente (v. verbete seguinte; Andoc., Pla.+; ins, pap, 4 Macc 1:35 v.l.[?]; Philo; Jos., Bell. 1, 206) honra especial (<span class=\"greek\">τιμή</span>) era concedida a pessoas que prestavam serviço excepcional ao Estado ou a outras instituições, e muitas pessoas abastadas empenhavam-se em superar umas às outras no serviço público filantrópico (cf. o bilionário Opramoas [IGR III, 739—II d.C.—trad. Danker, Benefactor 110–41], que provavelmente superou todos) ter por ambição, considerar uma honra, aspirar, com ênfase na ideia de prestar serviço, seguido de inf. (X., Mem. 2, 9, 3 e outros lugares; EpArist 79; Jos., Ant. 3, 207; 15, 330) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:9</a> (com <span class=\"greek\">εὐάρεστος</span>, v. esse verbete, termo frequentemente aplicado a filantropos); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:11.</a> V. verbete seguinte.—DELG s.v. <span class=\"greek\">τιμή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοτιμία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φιλοτιμία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">φιλότιμος</span> ‘amante da honra’, v. verbete anterior; Trag., Hdt.+; ins, pap; Wsd 14:18; EpArist 227; Philo; Jos., Ant. 10, 25 <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; em um recurso retórico: de aplicação inútil à enumeração de dados Ath., R. 18 p. 70, 16) zelo generoso <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κωφὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἐνδείκνυσθαι</span> <span class=\"greek\">φιλοτιμίαν</span> mostrar o mesmo zelo generoso para com os mudos (imagens) Dg 3:5 (cf. SIG 457, 42f).—V. <span class=\"greek\">δείκνυμι</span>. Larfeld I 501. DELG s.v. <span class=\"greek\">τιμή</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόϋλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φιλόϋλος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὕλη</span> ‘matéria’) amante das coisas materiais (cf. Origen, Fgm. in Luc. 71, linha 6 ed. MRauer 1930, p. 269 <span class=\"greek\">φιλοΰλων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φιλοσωμάτων</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">πιθανοί</span>) em imagem <span class=\"greek\">πῦρ</span> <span class=\"greek\">φιλόϋλον</span> um fogo que anseia por coisas materiais ou que deseja ser alimentado com coisas materiais IRo 7:2 (<span class=\"greek\">ὕλη</span> significa ‘coisas materiais’ em oposição a Deus 6:2, em outros lugares = ‘lenha’ [<span class=\"greek\">ὕλη</span> 2]).—DELG s.v. <span class=\"greek\">ὕλη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλοφρόνως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φιλοφρόνως</span> adv. de <span class=\"greek\">φιλόφρων</span> (Soph., Hdt. e outros; ins; BGU 1009, 3 [II a.C.]; 2 Macc 3:9; 4 Macc 8:5; EpArist 173; Jos., Ant. 11, 340, C. Ap. 2, 210) de maneira amigável, hospitaleiramente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:7</a> (Jos., Bell. 6, 115 <span class=\"greek\">φιλοφρόνως</span> <span class=\"greek\">ἐδέξατο</span>).—DELG s.v. <span class=\"greek\">φρήν</span> II.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιλόφρων, ον,</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φιλόφρων</span>, <span class=\"greek\">ον</span>, gen. <span class=\"greek\">ονος</span> (v. verbete anterior; Pind., X. e outros; PGrenf I 30, 5 [II a.C.]) bem-disposto, amigável, bondoso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:8</a> v.l.—DELG s.v. <span class=\"greek\">φρήν</span> II.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φίλων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φίλων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span> (nome frequentemente encontrado; literatura [p. ex. Diod S 16, 56, 3; 18, 7, 2; Tat. 34, 3], ins; PHib 45, 14 [257 a.C.]; BGU 1206, 6; 1207, 9 [ambos 28 a.C.]) Fílon, da Cilícia IPhld 11:1 que, com Reu Agátopo, está a serviço de Inácio, seguindo-o por Esmirna e Filadélfia, a fim de alcançá-lo em Trôade (v. Hdb. sobre IPhld 11:1). ISm 10:1; 13:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φιμόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φιμόω</span> (<span class=\"greek\">φιμός</span> ‘mordaça’; Aristoph. e outros; LXX; TestJob 27:3; Joseph.) inf. <span class=\"greek\">φιμοῦν</span> e, menos bem atestado, <span class=\"greek\">φιμοῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:15</a> v.l. (W-H., App. 166, Introd. §410; B-D-F §91; W-S. §13, 25); fut. <span class=\"greek\">φιμώσω</span>; 1.º aor. <span class=\"greek\">ἐφίμωσα</span>. Pass.: 1.º aor. <span class=\"greek\">ἐφιμώθην</span>; imperat. perf. 2.ª sing. <span class=\"greek\">πεφίμωσο</span>; ‘fechar amarrando’, especificamente fechar a boca com uma mordaça.</p><p class=\"entry-text\">① amordaçar, lit. <span class=\"greek\">οὐ</span> <span class=\"greek\">φιμώσεις</span> <span class=\"greek\">βοῦν</span> <span class=\"greek\">ἀλοῶντα</span> (Dt 25:4=Philo, De Virt. 145) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:9</a> v.l. (por <span class=\"greek\">κημώσεις</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:18.</a></p><p class=\"entry-text\">② silenciar, reduzir ao silêncio, extensão fig. de 1 (PGM 36, 164; IDefixAudollent 15, 24; 22, 42 mediante encantamento) <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:15.</a> Pass. ser silenciado ou ficar em silêncio (Lucian, Pereg. 15; Cyranides p. 64, 18; Jos., Bell. 1, 16; 438) <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐφιμώθη</span> mas ele ficou em silêncio=nada podia dizer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:12</a> (RBauckham, JBL 115, ’96, 486). Em exorcismos (ERohde, Psyche3 II 1903, 424) <span class=\"greek\">φιμώθητι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔξελθε</span> <span class=\"greek\">ἐξ</span> (<span class=\"greek\">ἀπ</span>’) <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:35.</a> Dirigido ao mar agitado <span class=\"greek\">σιώπα</span>, <span class=\"greek\">πεφίμωσο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:39</a> (B-D-F §346; Rob. 908).—DELG s.v. <span class=\"greek\">φιμός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φλαγελλόω</h1><div class=\"entry-meta\"><span>verbo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φλαγελλόω</span> (v. <span class=\"greek\">φραγέλλιον</span>) = <span class=\"greek\">φραγελλόω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:15</a> D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φλέγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φλέγω</span> fut. 3.ª sg. <span class=\"greek\">φλέξει</span> LXX, pass. <span class=\"greek\">φλεγήσεται</span> (Ps 88:47 Sym.) (Hom.+; ins; PSI 28, 12; PGM 4, 1732; LXX; TestSol 1:10; En; Philo, Op. M. 58; SibOr 3, 761) ‘queimar’, pass. ‘ser queimado, arder’.</p><p class=\"entry-text\">① estar em chamas, arder (Alciphron 1, 2, 1; Aristobulus: Eus., PE 8, 10, 13ff [p. 220, 10ff Denis=p. 144, 96 Holladay]; Jos., Bell. 6, 272) da lama no mundo inferior ApcPt 8:23.</p><p class=\"entry-text\">② experimentar uma emoção intensa, estar em chamas, extensão fig. de 1 (Chariton 8, 8, 7; Dio Chrys. 4, 52 <span class=\"greek\">φλεγόμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φιλοτιμίας</span>; Achilles Tat. 7, 3, 7; escólio sobre Nicander, Ther. 151; Anth. Pal. 16, 209 <span class=\"greek\">ὅλος</span> <span class=\"greek\">φλέγομαι</span>; Philo, Leg. All. 3, 224) <span class=\"greek\">ἐφλέγοντο</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀργῆς</span> estavam inflamados de ira GPt 12:50.—B. 75. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φλέγων, οντος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φλέγων</span>, <span class=\"greek\">οντος</span>, <span class=\"greek\">ὁ</span> (nome frequentemente encontrado entre escravos e libertos do sexo masculino; v. Ltzm., Hdb. sobre Ro 16:14) Flegonte (‘Aquele que arde’), cristão de outro modo desconhecido, destinatário de uma saudação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:14.</a>—DELG s.v. <span class=\"greek\">φλέγω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φλέψ, φλεβός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φλέψ</span>, <span class=\"greek\">φλεβός</span>, <span class=\"greek\">ἡ</span> (Hdt., Hippocr. e outros; PMich 149, 4, 35 [II d.C.]; Hos 13:15; Philo; Jos., Bell. 4, 462; em geral ‘vaso sanguíneo’) veia MPol 2:2 (sobre o assunto Jos., Bell. 2, 612).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φλογίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φλογίζω</span> (de <span class=\"greek\">φλέγω</span> por intermédio de <span class=\"greek\">φλόξ</span>) fut. 3.ª sg. <span class=\"greek\">φλογιεῖ</span> Ps 96:3; aor. 3.ª sg. <span class=\"greek\">ἐφλόγισε</span> LXX (Soph. e outros; LXX; PsSol 12:3; TestJob 16:3) atear fogo em imagem, <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:6a.</a> Pass. aor. 3.ª sg. <span class=\"greek\">ἐφλογίσθη</span> (Da 3:94 Theod.; Philostrat., Ep. 12 p. 230, 29 pelo amor) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:6b.</a>—NMacnicol, ET 55, ’43/44, 50–52.—DELG s.v. <span class=\"greek\">φλέγω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φλόξ, φλογός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φλόξ</span>, <span class=\"greek\">φλογός</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">φλέγω</span>; Hom.+; SIG 1170, 24; PGM 4, 3073; LXX; En; TestSol 3:4; TestJos 2:2; JosAs 14:9, também cod. A 12:10 [p. 56, 7 Bat.] por <span class=\"greek\">ἄβυσσον</span>; ApcEsdr 1:24 p. 25, 20 Tdf. [<span class=\"greek\">ἡ</span> <span class=\"greek\">φλόγα</span> codd.]; ApcSed 2:4; Philo; Jos., Bell. 6, 272, Ant. 13, 139; Ath. 22:7) chama <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:24.</a> <span class=\"greek\">φ</span>. <span class=\"greek\">πυρός</span> (Eur., Bacch. 8 e outros lugares; LXX; PsSol 15:4; JosAs 14:9; ViElijah 2 [p. 93, 11 Sch.]; <span class=\"greek\">πῦρ</span> b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:30</a> (Ex 3:2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:7</a>=1 Cl 36:3 (v. LRadermacher, Lebende Flamme: WienerStud 49, ’32, 115–18); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:14</a>; 2:18; 19:12 (sobre a associação com concepções antigas do ‘mau-olhado’, v. PDuff, NTS 43, ’97, 116–33). <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρὶ</span> <span class=\"greek\">φλογός</span> em fogo flamejante (Ex 3:2 B e outros; Sir 45:19; PsSol 12:4; a v.l. <span class=\"greek\">ἐν</span> <span class=\"greek\">φλογὶ</span> <span class=\"greek\">πυρός</span> é paralela ao texto de Is 66:15; cf. Ex 3:2; PKatz, ZNW 46, ’55, 133–38) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:8.</a> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">φ</span>. uma chama alta (Lucian, Tim. 6) MPol 15:1.—B. 72. DELG s.v. <span class=\"greek\">φλέγω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φλυαρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φλυαρέω</span> (<span class=\"greek\">φλύαρος</span>; Hdt. e outros; PSI 434, 7; 9 [III a.C.]; Sb 2266, 12; Tat. 33, 1; Iren., Orig., Hippol., Theoph.) entregar-se a uma fala sem sentido, dizer disparates (a respeito de), depreciar (Isocr. 5, 79 com <span class=\"greek\">βλασφημεῖν</span>; X., Hell. 6, 3, 12; Philo, Somn. 2, 291) com acus. de pessoa (cf. a pass. Diog. L. 7, 173 <span class=\"greek\">τὸν</span> <span class=\"greek\">Διόνυσον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἡρακλέα</span> <span class=\"greek\">φλυαρουμένους</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποιητῶν</span>=Dioniso e Héracles, vítimas da tagarelice dos poetas) e dat. de coisa <span class=\"greek\">λόγοις</span> <span class=\"greek\">πονηροῖς</span> <span class=\"greek\">φλυαρῶν</span> <span class=\"greek\">ἡμᾶς</span> depreciando-nos com afirmações ultrajantes ou tagarelando maliciosamente a nosso respeito (=falando mal de nós) 3J 10.—DELG s.v. <span class=\"greek\">φλύαρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φλύαρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φλύαρος</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">φλύω</span> ‘tagarelar’; Menand., Perinth. 15 S.; Dionys. Hal., Comp. Verbi 26 de escritores medíocres; Plut., Mor. 39a; 169e; 701a; Ps.-Pla., Axioch. 365e; 369a; Ps.-Lucian, Asin. 10; 4 Macc 5:11; Jos., Vi. 150) dado a mexericos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:13.</a>—Frisk s.v. <span class=\"greek\">φλυαρέω</span>; cf. DELG s.v. <span class=\"greek\">φλύω</span>. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοβερός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φοβερός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (de <span class=\"greek\">φόβος</span>, v. os três verbetes seguintes; Aeschyl. e outros) em nossa literatura somente no sentido ativo (comp. <span class=\"greek\">φοβερώτερος</span> [Just., D. 73, 6]; adv. <span class=\"greek\">φοβερῶς</span> [TestAbr A 17 p. 99, 24=Stone p. 46]) que causa medo, temível, terrível, assustador (Hdt. e outros; BGU 428, 8 [II d.C.]; LXX; pseudepígr., Philo; Jos., Bell. 4, 510, Ant. 3, 56; 88; Just.) <span class=\"greek\">φοβερὰ</span> <span class=\"greek\">ἐκδοχὴ</span> <span class=\"greek\">κρίσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:27</a> (cf. SibOr 3, 634 <span class=\"greek\">φοβ</span>. <span class=\"greek\">δίκη</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">φανταζόμενον</span> 12:21 (cf. Ezk. Trag. 125 [Eus., PE 9, 29, 11]). <span class=\"greek\">ἄκανθα</span> B 7:11. <span class=\"greek\">ἐπιθυμία</span> Hm 12, 1, 2. <span class=\"greek\">φοβερόν</span> (subent. <span class=\"greek\">ἐστιν</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμπεσεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:31.</a>—DELG s.v. <span class=\"greek\">φέβομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φοβέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φοβέω</span> (<span class=\"greek\">φέβομαι</span> ‘fugir aterrorizado’; Hom. e outros; Wsd 17:9; Jos., Ant. 14, 456), em nossa literatura somente pass. <span class=\"greek\">φοβέομαι</span> (Hom.+; OGI 669, 59; SIG 1268 II, 17; pap, LXX, pseudepígr., Philo, Joseph., Just.; Mel., P. 98, 746 e outros lugares; Ath. 20, 2; R. 21 p. 75, 1) imperf. <span class=\"greek\">ἐφοβούμην</span>; 1.º fut. <span class=\"greek\">φοβηθήσομαι</span>; 1.º aor. <span class=\"greek\">ἐφοβήθην</span> (Plut., Brut. 1002 [40, 9]; M. Ant. 9, 1, 7; Jer 40:9; Jos., C. Ap. 2, 277; v. B-D-F §79).</p><p class=\"entry-text\">① estar em estado de apreensão, ter medo, o aor. frequentemente no sentido de ficar assustado</p><p class=\"entry-text\">ⓐ intr., abs. (Iren. 1, 4, 2 [Harv. I 36, 4]) <span class=\"greek\">ἐφοβήθησαν</span> <span class=\"greek\">σφόδρα</span> ficaram terrivelmente assustados (Ex 14:10; 1 Macc 12:52) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:6</a>; 27:54. <span class=\"greek\">ἐπεστράφην</span> <span class=\"greek\">φοβηθείς</span> voltei-me aterrorizado Hv 4, 3, 7.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:8</a>; 14:30; 25:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:38.</a> <span class=\"greek\">ἐφοβοῦντο</span> <span class=\"greek\">γάρ</span> pois tinham medo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:8</a> (Mk 16:9–20 hoje raramente é considerado parte do evangelho original de Mc, embora muitos estudiosos duvidem de que o evangelho realmente terminasse com as palavras <span class=\"greek\">ἐφ</span>. <span class=\"greek\">γάρ</span>. O final original pode ter-se perdido; entre as possíveis razões apresentadas estão a perda acidental da última página da própria primeira cópia de Marcos [o mesmo defeito, em estágio muito antigo, no caso do 18.º livro dos <span class=\"greek\">Κεστοί</span> de Júlio Africano: WBauer, Orthodoxy etc. (trad. inglesa da 2.ª ed. alemã ’64) ’71, 159ff. V. também FKenyon, Papyrus Rolls and the Ending of St. Mk: JTS 40, ’39, 56f; CRoberts, The Ancient Book and the Ending of St. Mk: ibid. 253–57] ou a supressão deliberada, talvez porque divergisse dos outros relatos da ressurreição [para a omissão deliberada do final de um documento cf. Athen. 4, 61, 166d sobre o 10.º livro da Philippica de Teopompo, <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἧς</span> <span class=\"greek\">τινες</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τελευταῖον</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">χωρίσαντες</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δημαγωγῶν</span>. V. também Diog. L. 7, 34: relato de Isidoro de Pérgamo sobre a mutilação sistemática de livros da biblioteca local por Atenodoro, o estoico].—Aqueles que concluem que nada jamais veio depois de <span class=\"greek\">ἐφ</span>. <span class=\"greek\">γάρ</span> devem supor que o evangelista foi impedido de terminar sua obra [Zahn e outros], ou que de fato pretendeu encerrar o livro com essas palavras [v. <span class=\"greek\">γάρ</span> 1a]. Para uma frase breve, composta de verbo + <span class=\"greek\">γάρ</span>, v. também Epict. 3, 9, 19; 4, 8, 4; Artem. 4, 64; 1, 33 p. 35, 6; Plotinus, Ennead 5, 5, tratado que termina em <span class=\"greek\">γάρ</span> [PvanderHorst, JTS 23, ’72, 121–24]; Musonius Rufus, Tr. XII; Oenomaus em Eus., PE 6, 7, 8; Libanius, Or. 53 p. 65, 20 F.; PMich 149 VI, 37 [II d.C.]. Entre os que favorecem um final com <span class=\"greek\">γάρ</span>: Wlh., Loisy, Lohmeyer ad loc.; ABauer, WienerStud 34, 1912, 306ff; LBrun, D. Auferst. Christi 1925, 10ff; OLinton, ThBl 8, 1929, 229–34; JCreed, JTS 31, 1930, 175–80; MGoguel, La foi à la résurr. de Jésus ’33, 176ff; HMosbech, Mkevangeliets Slutning: SEÅ 5, ’40, 56–73; WAllen, JTS 47, ’46, 46–49 [‘sentir temor reverencial’]; ibid. 48, ’47, 201–3. V. também EGoodspeed, Exp. 8.ª série, 18, 1919, 155–60; reconstrução do final ‘perdido’, em inglês, por Goodsp. em sua Introd. to the NT ’37, 156; HProbyn, Exp. 9.ª série, 4, 1925, 120–25; RKevin, JBL 45, 1926, 81–103; MEnslin, ibid. 46, 1927, 62–68; HCadbury, ibid. 344f; MRist, ATR 14, ’32, 143–51; WKnox, HTR 35, ’42, 13ff; EHelzle, Der Schluss des Mk, ’59, diss. Tübingen; FDanker, CTM 38, ’67, 26f; JLuzarraga, Biblica 50, ’69, 497–510; KAland, MBlack Festschr., ’69, 157–80, NTEntwürfe, ’79, 246–83). <span class=\"greek\">φοβοῦμαι</span> <span class=\"greek\">μᾶλλον</span> tenho tanto mais medo IPhld 5:1. <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῆτε</span> não tenhais medo Mt 10:31 v.l. (<span class=\"greek\">μή</span> 1c<span class=\"greek\">ε</span><span class=\"hebrew\" dir=\"rtl\">א</span>). <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβοῦ</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβεῖσθε</span> não deveis mais ter medo, deixai de ter medo (<span class=\"greek\">μή</span> 1c<span class=\"greek\">γ</span><span class=\"hebrew\" dir=\"rtl\">א</span>) Mt 10:31; 14:27; 17:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:13,</a> 30; 2:10; 5:10; 8:50; 12:7 e outros lugares. LKöhler, D. Offenbarungsformel ‘Fürchte dich nicht!’: SchTZ 36, 1919, 33ff.—Com acus. de objeto interno (B-D-F §153; Rob. 468; Pla., Prot. 360b; Ael. Aristid. 30 p. 586 D.: <span class=\"greek\">φοβοῦμαι</span> <span class=\"greek\">φόβον</span>; Did., Gen. 230, 1; sobre o uso na LXX v. Johannessohn, Kasus 73) <span class=\"greek\">ὁ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">σε</span> <span class=\"greek\">φοβηθῆναι</span> o temor que deves ter Hm 7:1c. <span class=\"greek\">ἐφοβήθησαν</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">μέγαν</span> (Jon 1:10; 1 Macc 10:8; TestAbr. B 13 p. 117, 17f [Stone p. 82]; JosAs 6:1) tiveram muito medo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:9.</a> Se os substantivos devem ser tomados em sentido pass., também cabem aqui <span class=\"greek\">τὸν</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">αὐτῶν</span> (gen. objetivo) <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῆτε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a> (cf. Is 8:12) e <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβούμεναι</span> <span class=\"greek\">μηδεμίαν</span> <span class=\"greek\">πτόησιν</span> v. 6 (<span class=\"greek\">πτόησις</span> 2); v. 1b<span class=\"greek\">γ</span> abaixo.—Uma expressão helênica reconhecível (cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πολεμίων</span> <span class=\"greek\">φόβος</span>=medo diante do inimigo), embora favorecida pelo uso do AT (Lev 26:2; Dt 1:29; Jer 1:8, 17; Jdth 5:23; 1 Macc 2:62; 8:12; En 106:4; Helbing 29; B-D-F §149; Rob. 577) <span class=\"greek\">φοβ</span>. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> ter medo de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:28a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:4</a>; 1 Cl 56:11 (Job 5:22).—Seguido de gen. abs. 56:10. Seguido de <span class=\"greek\">μή</span> e do subj. aor. para denotar aquilo que se teme (Thu. 1, 36, 1; Aesop, Fab. 317 H.=356a P.; Alex. Aphr. 31, II/2 p. 203, 20 <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἀπόλλω</span> <span class=\"greek\">φοβεῖσθαι</span> <span class=\"greek\">μή</span> <span class=\"greek\">τι</span> <span class=\"greek\">παρελθῇ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἄπρακτον</span>=Apolo preocupa-se [quase tanto quanto ‘cuida’] para que nada disso fique por fazer; Jos., Ant. 10, 8, Vi. 252) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:10</a>; 27:17; ITr 5:1; Hs 9, 20, 2. Seguido de <span class=\"greek\">μήποτε</span> (Phlegon: 257 Fgm. 36, 2, 4 Jac. p. 1172, 30 <span class=\"greek\">φοβοῦμαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμῶν</span>, <span class=\"greek\">μήποτε</span>; JosAs 7:3; ApcMos 16 e outros lugares): Hm 12, 5, 3. <span class=\"greek\">φοβηθῶμεν</span> <span class=\"greek\">μήποτε</span> <span class=\"greek\">δοκῇ</span> <span class=\"greek\">τις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:1</a>; <span class=\"greek\">μήπου</span> (v.l. <span class=\"greek\">μήπως</span>; ParJer 5:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:3</a>; 12:20. Uma característica notável é a prolepse do objeto (cf. Soph., Oed. R. 767; Thu. 4, 8, 7) <span class=\"greek\">φοβοῦμαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">μήπως</span> <span class=\"greek\">εἰκῇ</span> <span class=\"greek\">κεκοπίακα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span> temo que meu trabalho convosco tenha sido em vão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:11</a> (B-D-F §476, 3; Rob. 423).—Seguido de inf. ter medo de fazer ou esquivar-se de fazer algo (B-D-F §392, 1b.—X., An. 1, 3, 17 e outros lugares; Gen 19:30; 26:7; ApcMos 10:18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>; 2:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:45</a>; 2 Cl 5:1.—<span class=\"greek\">φοβεῖσθαι</span> abs. no sentido de ter cuidado (Just., D. 78, 4) <span class=\"greek\">πλέον</span> <span class=\"greek\">φοβεῖσθαι</span> ter mais cuidado que de costume ITr 4:1.</p><p class=\"entry-text\">ⓑ trans. temer alguém ou algo</p><p class=\"entry-text\"><span class=\"greek\">α</span>. pessoas <span class=\"greek\">τινά</span> alguém (X., An. 3, 2, 19 e outros lugares; PGM 4, 2171; Num 21:34; Dt 3:2; Jos., Ant. 13, 26; Just., D. 83, 1) <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῆτε</span> <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:26.</a> <span class=\"greek\">Ἡρῴδης</span> <span class=\"greek\">ἐφοβεῖτο</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωάννην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:20.</a> <span class=\"greek\">τοὺς</span> <span class=\"greek\">Ἰουδαίους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:22</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:12</a>; 2:5b (dito de Jesus). Deus (Did., Gen. 64, 15; Theoph. Ant. 1, 14 [p. 92, 11]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:28b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:5abc</a>; 23:40; 2:5c (dito de Jesus). A multidão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:5</a>; 21:26, 46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:32</a>; 12:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:19</a>; 22:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:26</a> (seguido de <span class=\"greek\">μή</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐξουσίαν</span> (<span class=\"greek\">ἐξουσία</span> 5a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:3.</a> O anjo do arrependimento Hm 12, 4, 1; Hs 6, 2, 5. O cristão não deve ter medo do diabo Hm 7:2a; 12, 4, 6f; 12, 5, 2.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. animais (em imagem) <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβείσθωσαν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀρνία</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λύκους</span> 2:5a (dito de Jesus, de fonte desconhecida).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. coisas <span class=\"greek\">τὶ</span> algo (X., Hell. 4, 4, 8 e outros lugares; En 103:4; ApcEsdr 7:2 <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span>; Just., D. 1, 5 <span class=\"greek\">κόλασιν</span>; Ath., R. 21 p. 75, 1 <span class=\"greek\">οὐδέν</span>; Jos., C. Ap. 1, 90; 2, 232) <span class=\"greek\">τὸ</span> <span class=\"greek\">διάταγμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασιλέως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:23.</a> <span class=\"greek\">τὸν</span> <span class=\"greek\">θυμὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασιλέως</span> v. 27. <span class=\"greek\">τὴν</span> <span class=\"greek\">κρίσιν</span> 2 Cl 18:2. <span class=\"greek\">τὸν</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">θάνατον</span> Dg 10:7. <span class=\"greek\">φοβοῦμαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀγάπην</span>, <span class=\"greek\">μὴ</span> … IRo 1:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπλα</span> (em imagem) Hm 12, 2, 4.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a> e 6 pertencem aqui se os substantivos nessas passagens devem ser tomados em sentido ativo; v. 1a acima.—Temer, evitar, esquivar-se de <span class=\"greek\">τὶ</span> algo (Ps.-Callisth. 1, 41, 9 <span class=\"greek\">Δαρεῖος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅρμα</span> <span class=\"greek\">φοβηθείς</span>) <span class=\"greek\">τὴν</span> <span class=\"greek\">πλάνην</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτωλῶν</span> B 12:10. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span> Hm 7:3ac.—AVStröm, Der Hirt des Hermas, Allegorie oder Wirklichkeit? Ntl. Sem. Uppsala 3, ’36.</p><p class=\"entry-text\">② ter profundo respeito por, (ter) reverência, respeitar, com referência especial ao temor de ofender</p><p class=\"entry-text\">ⓐ Deus: temer (diferentemente de 1b<span class=\"greek\">α</span>) no sentido de reverenciar (Aeschyl., Suppl. 893 <span class=\"greek\">δαίμονας</span>; Isocr. 1, 16 <span class=\"greek\">τοὺς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">φοβοῦ</span>, <span class=\"greek\">τοὺς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">γονεῖς</span> <span class=\"greek\">τίμα</span>; Pla., Leg. 11, 927a; Lysias 9, 17; 32, 17; Plut., De Superstit. 2, 165b; LXX; PsSol 4:21; TestJob 43:9 [<span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>]; JosAs 2:5 [divindades]; Philo, Migr. Abr. 21 [segundo Gen 42:18]. Cf. PTebt 59, 10 [II a.C.] <span class=\"greek\">φοβεῖσθαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σέβεσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:50</a> (antecipa os <span class=\"greek\">οἱ</span> <span class=\"greek\">φοβούμενοι</span> em Ac: H-JKlauck, NTS 43, ’97, 134–39); 18:2, 4 (era Ex 23:1–3 seu lema: nem mesmo Deus poderia suborná-lo?); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:7</a>; 19:5; 1 Cl 21:7; 23:1; 28:1; 45:6; B 10:10f (<span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>); 19:2, 7; Hm 1:2; 7:1, 4f; Hs 5, 1, 5; 8, 11, 2; D 4:10. Também <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (2 Esdr 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18.</a>—<span class=\"greek\">φοβούμενοι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> como termo técnico=<span class=\"greek\">σεβόμενοι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> (<span class=\"greek\">σέβω</span> 1b; caráter técnico contestado por MWilcox, JSNT 13, ’81, 102–22; cf. TFinn, CBQ 47, ’85, 75–84; ILevinskaya, The Book of Acts in Its Diaspora Setting [BAFCS V] ’96, 51–126; BWander, Gottesfürchtige und Sympathisanten [WUNT 104] ’98, especialmente 80–86; 180–203) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:16,</a> 26 (Just., D. 10, 4 e outros lugares; sing. 10:2, 22).—<span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> (PsSol 2:33; 3:12 e outros lugares; JosAs 8:9) Cristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:22.</a>—WAllen (v. 1a acima) interpreta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:8</a> no sentido de reverência pelo divino.</p><p class=\"entry-text\">ⓑ pessoas que impõem respeito (Plut., Galba 1054 [3, 4]; Herodian 3, 13, 2; Lev 19:3 <span class=\"greek\">φοβ</span>. <span class=\"greek\">πατέρα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μητέρα</span>; Jos., Ant. 19, 345): de uma esposa <span class=\"greek\">ἵνα</span> <span class=\"greek\">φοβῆται</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνδρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:33.</a> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐπίσκοπον</span> IEph 6:1.—RAC VIII 661–99; TRE XI 756–59; Schmidt, Syn. III 507–36. DELG s.v. <span class=\"greek\">φέβομαι</span> II. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόβητρον e φόβηθρον</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φόβητρον</span> e <span class=\"greek\">φόβηθρον</span> (<span class=\"greek\">φοβέω</span>; sufixos diferentes; v. B-D-F §35, 3; Mlt-H. 110; Thackeray 104), <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hippocr., Morb. Sacr. 1 vol. Vl p. 362 L.; Ps.-Pla., Axioch. 367a; Lucian, Alex. 25; Anth. Pal. 11, 189, 3 Düb.; Is 19:17) algo incomum que causa medo, visão/acontecimento terrível, horror. Pl. <span class=\"greek\">φόβητρά</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">ἔσται</span> haverá portentos terríveis e sinais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11.</a>—DELG s.v. <span class=\"greek\">φέβομαι</span> II.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0379-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φόβος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φόβος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. os três verbetes anteriores; Hom.+. Em Hom. ‘fuga em pânico’; depois em vários sentidos).</p><p class=\"entry-text\">① entidade intimidante, o sentido ativo causativo</p><p class=\"entry-text\">ⓐ intimidação (Appian, Bell. Civ. 3, 27 §104 <span class=\"greek\">ἐς</span> <span class=\"greek\">φ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">βουλῆς</span>=intimidar o Senado) assim provavelmente <span class=\"greek\">τὸν</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῆτε</span> não vos deixeis intimidar pela intimidação deles (cf. REB e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a> (Is 8:12; v. <span class=\"greek\">φοβέω</span> 1b<span class=\"greek\">γ</span> e cf. 2a<span class=\"greek\">α</span> abaixo).</p><p class=\"entry-text\">ⓑ concretamente, algo terrível/que inspira temor, um terror (Soph., Philoct. 1251; Polyb. 11, 30, 2; Appian, Bell. Civ. 2, 135 §565; SIG 442, 10 [III a.C.] <span class=\"greek\">οὐδένα</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">κίνδυνον</span> <span class=\"greek\">ὑποστελλόμενοι</span>; Just., A II, 5, 4 <span class=\"greek\">διὰ</span> <span class=\"greek\">φόβων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τιμωριῶν</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐπέφερον</span>) <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄρχοντες</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">φόβος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:3.</a> Assim talvez também <span class=\"greek\">εἰδότες</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> visto que sabemos o que causa temor do Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:11</a> (isto é, o juízo vindouro, v. 10; assim Goodsp., REB e outros; ambiguamente NRSV; v. também Field, Notes 183f); v. 2b<span class=\"greek\">α</span> abaixo.</p><p class=\"entry-text\">② produto de uma força intimidante/alarmante, o sentido passivo</p><p class=\"entry-text\">ⓐ medo, alarme, susto</p><p class=\"entry-text\"><span class=\"greek\">α</span>. em geral <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:17</a> (sentido de medo do juiz vindouro, a menos que <span class=\"greek\">ἐν</span> <span class=\"greek\">φ</span>. aqui signifique reverentemente, como ESelwyn, 1 Pt ’46, 143); Jd 23 (sentido de medo de contaminar-se); Dg 7:3. Com <span class=\"greek\">τρόμος</span> (v. esse verbete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:15</a>; 1 Cl 12:5. Pl. temores, apreensões, sentimentos de ansiedade (já em Thu. e outros; Diod S 16, 3, 1; 16, 42, 9 Ptolemy, Apotel. 2, 9, 5; Appian, Bell. Civ. 1, 16 §67; 3, 89 §368; SIG 326, 21 [307/306 a.C.]; Job 20:25; Wsd 18:17; Jos., Ant. 10, 24; 15, 44) <span class=\"greek\">ἔξωθεν</span> <span class=\"greek\">μάχαι</span> <span class=\"greek\">ἔσωθεν</span> <span class=\"greek\">φόβοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:5.</a> <span class=\"greek\">παράγειν</span> <span class=\"greek\">φόβους</span> <span class=\"greek\">ἀνθρωπίνους</span> introduzir temores de seres humanos 2 Cl 10:3.—Com gen. objetivo de pessoa (Diod S 10, 19, 6 <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Περσῶν</span> <span class=\"greek\">φόβος</span>), ou de coisa (Jos., C. Ap. 1, 259; Ath. 1, 1 <span class=\"greek\">φόβῳ</span> <span class=\"greek\">δίκης</span>; Did., Gen. 171, 14) que causa medo <span class=\"greek\">ὁ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span> o medo dos judeus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:13</a>; 19:38; 20:19. <span class=\"greek\">φόβος</span> <span class=\"greek\">θανάτου</span> medo da morte (Epict. 2, 1, 14; 2, 18, 30 e outros; TestAbr B 14 p. 118, 24 [Stone p. 84]; Philo, Omn. Prob. Lib. 111; Ath., R. 22 p. 75, 17; Orig., C. Cels. 1, 61, 37) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:15.</a> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασανισμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:10,</a> 15. <span class=\"greek\">νόμου</span> Dg 11:6.—<span class=\"greek\">ἀπὸ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">φόβου</span> (<span class=\"greek\">τινός</span>) por causa do medo, por medo (de alguém) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:26</a>; 28:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:26</a>; Hm 11:14. Também <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φόβον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:14</a> v.l. (Hyperid. 5, 5 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φ</span>.; Arrian, Anab. 5, 15, 6 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φ</span>.; Artem. 1, 1 p. 3, 23 <span class=\"greek\">διὰ</span> <span class=\"greek\">φόβον</span>; TestAbr B 14 p. 118, 24 [Stone p. 84]; Philo, Mos. 1, 164 <span class=\"greek\">διὰ</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">τινός</span>; Jos., Vi. 354 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φόβον</span>; Just., A II, 9, 1 <span class=\"greek\">διὰ</span> <span class=\"greek\">φόβον</span>). <span class=\"greek\">μετὰ</span> <span class=\"greek\">φόβου</span> com medo ou em temor (Aeneas Tact. 1257; TestAbr A 16 p. 96, 22 [Stone p. 40]; GrBar 13:1) do sentimento que acompanha uma ação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:8</a>; Dg 12:6; AcPl Ha 11, 12.—Como sujeito (En 100:8): <span class=\"greek\">φόβος</span> <span class=\"greek\">πίπτει</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> medo sobrevém a alguém Ac 19:17 v.l.; Rv 11:11 v.l. <span class=\"greek\">ἐπιπίπτει</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:12</a>; Ac 19:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:11.</a> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:43b</a> v.l. <span class=\"greek\">γίνεται</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.65\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:65</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:5,</a> 11 ou <span class=\"greek\">γίνεταί</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:43a.</a> <span class=\"greek\">λαμβάνει</span> <span class=\"greek\">τινά</span> (Jos., Vi. 148) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:16</a>; Hv 5:4. <span class=\"greek\">πλησθῆναι</span> <span class=\"greek\">φόβου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:26.</a> <span class=\"greek\">φόβῳ</span> <span class=\"greek\">συνέχεσθαι</span> 8:37; AcPl Ha 3, 33; 11, 16. <span class=\"greek\">φόβον</span> <span class=\"greek\">ἔχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:20</a>; Hm 7:2c; 12, 4, 7a; Hs 1:10. <span class=\"greek\">φοβεῖσθαι</span> <span class=\"greek\">φόβον</span> (<span class=\"greek\">μέγαν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:9</a>; cf. <span class=\"greek\">τὸν</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβηθῆτε</span> não temais o que eles temem (NRSV; semelhantemente outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a> (mas v. 1 acima); Hm 7:1 (<span class=\"greek\">φοβέω</span> 1a).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. especificamente do medo servil (Diog. Cyn. em Diog. L. 6, 75 <span class=\"greek\">δούλου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φοβεῖσθαι</span>), que não deve caracterizar a relação do cristão com Deus <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐλάβετε</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">δουλείας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φόβον</span> não recebestes espírito de escravidão, para vos causar medo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:15.</a> Cf. 1J 4:18abc (oposto a <span class=\"greek\">ἀγάπη</span>; cf. <span class=\"greek\">κόλασις</span> 2, final).</p><p class=\"entry-text\">ⓑ reverência, respeito</p><p class=\"entry-text\"><span class=\"greek\">α</span>. para com Deus (Polyaenus 1, 16, 1; LXX; PsSol 6:5 e outros lugares; EpArist 159 <span class=\"greek\">ὁ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φόβος</span>; 189; cf. <span class=\"greek\">φόβος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θεῖα</span> <span class=\"greek\">τοῖσι</span> <span class=\"greek\">σώφροσιν</span> <span class=\"greek\">βροτῶν</span> TGF, Adesp. n.º 356 p. 906) e Cristo, com <span class=\"greek\">τρόμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a> (v. <span class=\"greek\">τρόμος</span>). Com <span class=\"greek\">ἀλήθεια</span> 1 Cl 19:1; Pol 2:1. Com <span class=\"greek\">ἀγάπη</span> 1 Cl 51:2. Com <span class=\"greek\">εὐλάβεια</span> Pol 6:3. Com <span class=\"greek\">πίστις</span>, <span class=\"greek\">εἰρήνη</span> e outras coisas boas e virtudes 1 Cl 64. Com <span class=\"greek\">ὑπομονή</span> B 2:2. Com <span class=\"greek\">ἐλπὶς</span>: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> 11:11. Com <span class=\"greek\">πίστις</span> e <span class=\"greek\">ἐγκράτεια</span> Hm 6, 1, 1. Com gen. objetivo <span class=\"greek\">φόβος</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">θεοῦ</span> (PLond 1914, 12 <span class=\"greek\">φόβον</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span>; Philo, Spec. Leg. 4, 199; TestLevi 13:7; TestNapht 2:9; Theoph. Ant. 1, 7 [p. 72, 26]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:18</a> (Ps 35:2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:1</a> (<span class=\"greek\">ἀγάπη</span> P46); 1 Cl 3:4; 21:6; cf. 8; B 4:11; 19:5; 20:2; Pol 4:2; Hm 10, 1, 6a; 12, 2, 4bc; D 4:9. <span class=\"greek\">φόβος</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">κυρίου</span> (TestReub 4:1; TestSim 3:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:31</a>; 1 Cl 22:1 (Ps 33:12); 57:5 (Pr 1:29); B 11:5 (Is 33:18 v.l.); Hm 7:4b; 8:9; 10, 1, 6b; 12, 2, 4a; 12, 3, 1. Alguns situam aqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:11</a> (v. 1b acima). <span class=\"greek\">φόβος</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:21.</a>—Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:17</a> v. 2a<span class=\"greek\">α</span> início.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. para com seres humanos, respeito devido a autoridades (cf. Byzantinische Papyri [Munique], ed. AHeisenberg/LWenger, 1914, n.º 2, linha 13 p. 43: <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φόβον</span> … <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμετέρας</span> <span class=\"greek\">ἐνδόξου</span> <span class=\"greek\">ὑπεροχῆς</span>=tendo respeito por vossa estimada autoridade) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:7ab</a> (CCranfield, NTS 6, ’60, 241–49: a referência pode ser a Deus); do escravo para com o senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:5</a> (com <span class=\"greek\">τρόμος</span>); B 19:7=D 4:11 (com <span class=\"greek\">αἰσχύνη</span>); da esposa para com o marido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:2</a> (cf. SEG XXXV, 1427, 5 [III d.C.]). Em geral 3:16 (com <span class=\"greek\">πραΰτης</span>).—WLütgert, Die Furcht Gottes: MKähler Festschr. 1905, SBerkelbach v.der Sprenkel, Vrees en Religie 1920, 165ff; RSander, Furcht u. Liebe im palästin. Judentum ’35.—B. 1153. DELG s.v. <span class=\"greek\">φέβομαι</span> I. M-M. EDNT. TW. Sv.</p></section></article>"};
